import{_ as i,o as s,c as t,ag as e}from"./chunks/framework.TQKaXlFR.js";const k=JSON.parse('{"title":"数据库迁移","description":"","frontmatter":{},"headers":[],"relativePath":"reference/database-migrations.md","filePath":"reference/database-migrations.md"}'),n={name:"reference/database-migrations.md"};function l(r,a,d,h,o,p){return s(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="数据库迁移" tabindex="-1">数据库迁移 <a class="header-anchor" href="#数据库迁移" aria-label="Permalink to &quot;数据库迁移&quot;">​</a></h1><p>本页面向部署者和数据库维护人员，用于空库初始化、存量库升级与迁移失败恢复。前提是确认数据库归属、代码版本与备份方案；本页不授权清理现有业务库。</p><h2 id="配置与目录" tabindex="-1">配置与目录 <a class="header-anchor" href="#配置与目录" aria-label="Permalink to &quot;配置与目录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>当前行为</th></tr></thead><tbody><tr><td>数据库建立</td><td>部署者先创建 schema，Flyway 不创建数据库</td></tr><tr><td>主连接</td><td><code>DB_URL/DB_USERNAME/DB_PASSWORD</code> 同时供 Flyway 和 dynamic-datasource 主库</td></tr><tr><td>默认 location</td><td><code>classpath:db/migration</code></td></tr><tr><td>历史 optional location</td><td><code>classpath:db/optional-migration</code>，仅在环境需要时显式保留</td></tr><tr><td>baseline</td><td><code>baseline-on-migrate=false</code>，<code>baseline-version=2</code> 仅为经评估的历史基线预留</td></tr><tr><td>校验与顺序</td><td>validate-on-migrate=true，out-of-order=false，严格 missing 校验</td></tr><tr><td>清理</td><td>clean-disabled=true；不用 clean/删 history 解决故障</td></tr></tbody></table><p><code>sql/xinghui_admin.sql</code> 是历史导出，不能作为当前初始化方式。旧文档写的 DB_HOST/DB_NAME 自动拼接、默认自动 baseline 已过期。</p><h2 id="版本与-repeatable" tabindex="-1">版本与 repeatable <a class="header-anchor" href="#版本与-repeatable" aria-label="Permalink to &quot;版本与 repeatable&quot;">​</a></h2><p>当前目录有 <strong>22 个 versioned SQL</strong>，从 V1/V2 到 <code>V20261013_170__menu_consolidation.sql</code>。版本按 Flyway 数值段比较，不以字符串排序或文件修改时间判断先后。新增脚本前核对当前分支所有版本，不能复用已存在的版本号。</p><table tabindex="0"><thead><tr><th>迁移阶段</th><th>作用</th></tr></thead><tbody><tr><td>V1 / V2</td><td>基础表与种子；包括公开初始化账号，部署后立即处理</td></tr><tr><td>20260726 系列</td><td>文件权限、旧结构对齐、字符集/排序规则</td></tr><tr><td>20260926 系列</td><td>参数运行态、字典、受控调度、通知、AI模型/场景、微信授权</td></tr><tr><td>20261012.120–160</td><td>内容权限、历史网站管理建立与退役、菜单清理、加密业务配置、低代码</td></tr><tr><td>20261013.170</td><td>三个一级组、叶子归并与权限关联迁移</td></tr></tbody></table><p>V130 曾建立网站内容表；V140 已退役这些表/菜单。应保留历史版本链，不删除旧脚本来假装模块从未存在。optional 下同名 R 脚本用于历史资料示例清理，不再创建示例表。曾使用该 location 的库，后续必须保留，才能校验已应用 repeatable 历史。</p><p>当前质量验证环境启用了两个 location，实测 <code>history=23</code>（22 versioned + 清理 R）。默认仅 versioned 的新库不应机械要求23行；判断依据是每条 script/version/type/success 与本环境 location 匹配。</p><h2 id="空库启动" tabindex="-1">空库启动 <a class="header-anchor" href="#空库启动" aria-label="Permalink to &quot;空库启动&quot;">​</a></h2><ol><li>建立专属 utf8mb4/general_ci schema 和账号，确保表数为0。</li><li>设置完整 <code>DB_URL</code> 及账号；检查自己连接的 schema。</li><li>保持 baseline 默认 false，启动当前后端。</li><li>查看 V1/V2 及后续迁移日志，查询完整 history。</li><li>重新启动，确认严格校验成功且原有业务数据保留。</li></ol><div class="language-sql vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DATABASE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">CURRENT_USER</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(), </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">VERSION</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> COUNT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> table_count</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> information_schema</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">tables</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> table_schema</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=DATABASE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, script, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">checksum</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, success</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> flyway_schema_history </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ORDER BY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> installed_rank;</span></span></code></pre></div><p>其中表数检查是在首次启动前进行；已有 history 后不能把该步骤转成删表命令。应用代码还依赖 Redis/JWT，不能只凭数据库迁移成功断言整个应用启动验证完成。</p><h2 id="存量库与基线" tabindex="-1">存量库与基线 <a class="header-anchor" href="#存量库与基线" aria-label="Permalink to &quot;存量库与基线&quot;">​</a></h2><p>有业务表但没有 history 的库不会默认自动接受 V2 baseline。先对比其结构、种子、租户数据、当前脚本及依赖版本；规划人工基线或前向迁移，经负责人确认、备份/恢复演练和窗口准备后实施。</p><p>baseline=2 表示将 V1/V2 视为已有，并非自动补齐这两份 SQL 的所有内容。旧结构不一致时，盲目启用 baseline 会留下缺表/字段/权限。不要通过全局设置 <code>baseline-on-migrate=true</code> 把未知库连接问题吞掉。具体升级流程见<a href="./../releases/upgrade.html">升级</a>。</p><h2 id="增加与修复迁移" tabindex="-1">增加与修复迁移 <a class="header-anchor" href="#增加与修复迁移" aria-label="Permalink to &quot;增加与修复迁移&quot;">​</a></h2><p>成功执行过的 versioned SQL 不再修改；修复用更高版本的新脚本。采用具名列、显式字符集/排序规则，评估旧数据和权限关联。MySQL DDL 可能自动提交，失败不能假定整份脚本自动回滚。</p><p>迁移失败时停止反复启动，保留目标 commit、history 和错误短摘要，检查实际 DDL/DML 已完成部分。checksum mismatch、missing migration 与 SQL 执行失败不同，不能一律执行 <code>repair</code>。只有经审查确认 schema 与历史一致的方案才考虑 repair；它不会替你修复业务结构。</p><p>不得随意删库、清表、删除 <code>flyway_schema_history</code> 或将 out-of-order/ignore-migration-patterns 改宽来得到绿灯。需要回退时按<a href="./../operations/backup-restore.html">备份恢复</a>成套恢复 DB、主密钥、对象与配套代码。</p><h2 id="已验证与源码依据" tabindex="-1">已验证与源码依据 <a class="header-anchor" href="#已验证与源码依据" aria-label="Permalink to &quot;已验证与源码依据&quot;">​</a></h2><p>当前开发候选在隔离 MySQL8.0.12 空库完成含 V170 的23条 history、重启 strict validate、真实认证/SQL/MinIO和夹具清理。MySQL5.7/8.0容器矩阵及独立机器未运行；这些本地结果不替代目标环境升级演练。</p><p>源码：后端 <code>system-admin/src/main/resources/application.yml</code>、<code>application-datasource.yml</code>、<code>db/migration/*.sql</code>、<code>db/optional-migration/*.sql</code>、<code>system-admin/src/test/java/com/xinghuiTec/quality/ReleaseServicesIT.java</code>；版本组合见<a href="./../releases/versions.html">版本页</a>。</p>`,24)])])}const E=i(n,[["render",l]]);export{k as __pageData,E as default};
